func activityDotColor(eventType string) string {
	switch eventType {
	case "message":
		return "bg-blue-400"
	case "tool_call":
		return "bg-yellow-400"
	case "error":
		return "bg-red-400"
	case "session_meta":
		return "bg-teal-400"
	default:
		return "bg-gray-400"
	}
}

func activityLabel(eventType string) string {
	switch eventType {
	case "message":
		return "message"
	case "tool_call":
		return "tool"
	case "error":
		return "error"
	case "session_meta":
		return "session"
	default:
		return eventType
	}
}

func activityBadgeStyle(eventType string) string {
	switch eventType {
	case "message":
		return "bg-blue-500/15 text-blue-400"
	case "tool_call":
		return "bg-yellow-500/15 text-yellow-400"
	case "error":
		return "bg-red-500/15 text-red-400"
	case "session_meta":
		return "bg-teal-500/15 text-teal-400"
	default:
		return "bg-gray-600/40 text-gray-400"
	}
}

